<template>
  <canvas ref="canvasEl" class="matrix-rain" aria-hidden="true" />
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'

/**
 * 页面背景：经典「矩阵雨」。
 *
 * 它属于页面氛围而不是组件本身 —— comps-vue3 的 CyberInput / TerminalAuth 只保留面板自己的效果，
 * 全屏矩阵雨放在 demo 里自己画，宿主想换背景时不用改组件。半透明底色覆盖形成拖尾，
 * 字符随机取片假名 / 十六进制，少量换成强调色。
 */
const props = defineProps<{
  /** 主色（大部分字符） */
  color?: string
  /** 强调色（少量高亮字符） */
  accent?: string
  /** 拖尾覆盖色，需和舞台底色一致 */
  background?: string
  /** 整体不透明度 */
  opacity?: number
}>()

const canvasEl = ref<HTMLCanvasElement | null>(null)
const rootStyle = computed(() => ({ opacity: String(props.opacity ?? 0.18) }))

const CHARS = 'アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン0123456789ABCDEF<>{}[]|'
const FONT_SIZE = 14

let ctx: CanvasRenderingContext2D | null = null
let drops: number[] = []
let rafId = 0
let width = 0
let height = 0
let observer: ResizeObserver | null = null

function resize() {
  const canvas = canvasEl.value
  if (!canvas) return
  const parent = canvas.parentElement
  width = canvas.width = parent?.clientWidth || window.innerWidth
  height = canvas.height = parent?.clientHeight || window.innerHeight
  drops = new Array(Math.ceil(width / FONT_SIZE)).fill(1).map(() => Math.random() * -50)
}

function draw() {
  if (!ctx) return
  ctx.fillStyle = props.background ?? 'rgba(13, 13, 13, 0.06)'
  ctx.fillRect(0, 0, width, height)
  ctx.font = `${FONT_SIZE}px monospace`

  const accent = props.accent ?? '#ff2a6d'
  const color = props.color ?? '#05d9e8'

  for (let i = 0; i < drops.length; i += 1) {
    const char = CHARS[Math.floor(Math.random() * CHARS.length)]
    const accentChar = Math.random() > 0.93
    ctx.globalAlpha = accentChar ? 1 : 0.35 + Math.random() * 0.6
    ctx.fillStyle = accentChar ? accent : color

    ctx.fillText(char, i * FONT_SIZE, drops[i] * FONT_SIZE)
    ctx.globalAlpha = 1

    if (drops[i] * FONT_SIZE > height && Math.random() > 0.975) drops[i] = 0
    drops[i] += 1
  }

  rafId = requestAnimationFrame(draw)
}

function stop() {
  if (rafId) cancelAnimationFrame(rafId)
  rafId = 0
}

function onVisibilityChange() {
  if (document.hidden) stop()
  else if (!rafId) rafId = requestAnimationFrame(draw)
}

onMounted(() => {
  const canvas = canvasEl.value
  if (!canvas) return
  ctx = canvas.getContext('2d')
  resize()
  observer = new ResizeObserver(resize)
  if (canvas.parentElement) observer.observe(canvas.parentElement)
  document.addEventListener('visibilitychange', onVisibilityChange)
  rafId = requestAnimationFrame(draw)
})

onBeforeUnmount(() => {
  stop()
  observer?.disconnect()
  document.removeEventListener('visibilitychange', onVisibilityChange)
})
</script>

<style scoped>
.matrix-rain {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
</style>
